void CHitParameters::SetWeapon(CThing& weapon)
{
    PWeapon = &weapon;
    const CTCObjectAugmentations* ptc;
    if (PWeapon->PeekTC(&ptc)) {
        std::vector<long> augmentations;
        ptc->GetAugmentations(augmentations);
